B.arn=s(["Bacon \u2192 jam\xf3n o pavo."],t.s)
B.bbM=new A.a9(B.r,B.v5,null,"Bacon crujiente y huevo cuajado pero jugoso.",B.azw,B.j,B.arn,"Para comer al momento.",null,B.p)
